import json,re
async def s(q,pats=None,n=5,w=300):
    r=json.loads(await web_search({"query":q}))
    print("##",q)
    for x in r[:n]:
        if x.get('type')!='web_search_result': print(x);continue
        c=x['content']
        print("-",x['url'],len(c))
        if pats:
            for p in pats:
                for m in list(re.finditer(p,c))[:3]:
                    print("   ",c[max(0,m.start()-50):m.start()+w].replace("\n"," "))
        else: print(c[:w])
await s("Apple 10-K FY2025 net sales operating income net income",["FY2025|2024-09-29 to 2025-09-27"],3,200)

