def show(r,pats,n=6,pre=60,post=220,maxhits=2):
    for x in r[:n]:
        print(x['url']);c=x['content']
        for p in pats:
            for m in list(re.finditer(p,c))[:maxhits]: print("  >",c[max(0,m.start()-pre):m.start()+post].replace("\n"," "))
